CREATE TABLE IF NOT EXISTS schema_versions(version integer PRIMARY KEY, applied_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE users(id text PRIMARY KEY, email text NOT NULL UNIQUE, name text NOT NULL, password text NOT NULL, admin boolean NOT NULL DEFAULT false, totp bytea, pending_totp bytea, recovery text[] NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE sessions(token text PRIMARY KEY, user_id text NOT NULL REFERENCES users(id) ON DELETE CASCADE, csrf text NOT NULL, expires_at timestamptz NOT NULL);
CREATE TABLE resources(id text PRIMARY KEY, kind text NOT NULL, name text NOT NULL, team_id text NOT NULL DEFAULT '', parent_id text NOT NULL DEFAULT '', data jsonb NOT NULL DEFAULT '{}', secret bytea, version integer NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX resources_parent ON resources(parent_id,kind);
CREATE INDEX resources_team ON resources(team_id,kind);
CREATE TABLE team_members(team_id text NOT NULL REFERENCES resources(id) ON DELETE CASCADE,user_id text NOT NULL REFERENCES users(id) ON DELETE CASCADE,role text NOT NULL CHECK(role IN ('owner','member')),PRIMARY KEY(team_id,user_id));
CREATE TABLE project_members(project_id text NOT NULL REFERENCES resources(id) ON DELETE CASCADE,user_id text NOT NULL REFERENCES users(id) ON DELETE CASCADE,role text NOT NULL CHECK(role IN ('owner','operator','viewer')),PRIMARY KEY(project_id,user_id));
CREATE TABLE resource_grants(resource_id text NOT NULL REFERENCES resources(id) ON DELETE CASCADE,team_id text NOT NULL REFERENCES resources(id) ON DELETE CASCADE,PRIMARY KEY(resource_id,team_id));
CREATE TABLE invitations(id text PRIMARY KEY,token text NOT NULL UNIQUE,email text NOT NULL,team_id text NOT NULL REFERENCES resources(id) ON DELETE CASCADE,project_id text NOT NULL DEFAULT '',role text NOT NULL,expires_at timestamptz NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE deployments(id text PRIMARY KEY,app_id text NOT NULL REFERENCES resources(id),state text NOT NULL DEFAULT 'queued',phase text NOT NULL DEFAULT 'queued',commit_sha text NOT NULL DEFAULT '',error text NOT NULL DEFAULT '',release_id text NOT NULL DEFAULT '',rollback_id text NOT NULL DEFAULT '',snapshot bytea NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX deployments_app ON deployments(app_id,created_at DESC);
CREATE TABLE releases(id text PRIMARY KEY,app_id text NOT NULL REFERENCES resources(id),deployment_id text NOT NULL REFERENCES deployments(id),snapshot bytea NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE app_runtime(app_id text PRIMARY KEY REFERENCES resources(id),release_id text NOT NULL REFERENCES releases(id),status text NOT NULL DEFAULT 'running',runtime jsonb NOT NULL DEFAULT '{}',updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE events(id bigserial PRIMARY KEY,deployment_id text NOT NULL REFERENCES deployments(id) ON DELETE CASCADE,message text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX events_deployment ON events(deployment_id,id);
CREATE TABLE jobs(id text PRIMARY KEY,kind text NOT NULL,resource_id text NOT NULL,payload jsonb NOT NULL DEFAULT '{}',state text NOT NULL DEFAULT 'queued',attempts integer NOT NULL DEFAULT 0,available_at timestamptz NOT NULL DEFAULT now(),lease_until timestamptz,worker text,last_error text NOT NULL DEFAULT '',dedupe text UNIQUE,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX jobs_queue ON jobs(available_at) WHERE state IN ('queued','running');
CREATE TABLE webhook_deliveries(provider_id text NOT NULL REFERENCES resources(id),delivery_id text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(provider_id,delivery_id));
CREATE TABLE domain_state(route_id text PRIMARY KEY REFERENCES resources(id) ON DELETE CASCADE,zone_id text REFERENCES resources(id),domain text NOT NULL,certificate_domain text NOT NULL DEFAULT '',records jsonb NOT NULL DEFAULT '[]',dns_state text NOT NULL DEFAULT 'pending',propagation_state text NOT NULL DEFAULT 'pending',certificate_state text NOT NULL DEFAULT 'pending',routing_state text NOT NULL DEFAULT 'pending',certificate bytea,expires_at timestamptz,last_error text NOT NULL DEFAULT '',updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE metrics(id bigserial PRIMARY KEY,resource_id text NOT NULL REFERENCES resources(id) ON DELETE CASCADE,data jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX metrics_resource ON metrics(resource_id,created_at DESC);
CREATE TABLE audit(id bigserial PRIMARY KEY,user_id text NOT NULL,action text NOT NULL,resource_id text NOT NULL DEFAULT '',team_id text NOT NULL DEFAULT '',detail jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE alert_state(resource_id text NOT NULL,kind text NOT NULL,active boolean NOT NULL DEFAULT false,since timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(resource_id,kind));
CREATE TABLE settings(key text PRIMARY KEY,value jsonb NOT NULL);
INSERT INTO settings(key,value) VALUES('maintenance','false');
